-- ONE-798: restore the independently approved online-renewal configuration.
-- Target: Supabase dwoahbduwzfzqmwpvadj / private booking schema.
-- One atomic DO statement; stop on existing project rather than overwrite.
-- IDs are generated by the current database; no historical bookings are imported.
DO $restore$
DECLARE
  renewal_id integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('ONE-798-renewal-restore'));
  IF EXISTS (SELECT 1 FROM booking.booking_templates WHERE "bt_projectId" = 'renewal') THEN
    RAISE EXCEPTION 'renewal already exists; inspect it instead of replaying the restore';
  END IF;

  INSERT INTO booking.booking_templates (
    "bt_projectId", bt_name, "bt_templateType", "bt_liffId",
    "bt_ragicSearchPath", "bt_ragicUidField", "bt_ragicTaskPath",
    "bt_slotDurationMinutes", "bt_bookableDaysAhead",
    "bt_dailyStartTime", "bt_dailyEndTime", "bt_bufferMinutes", "bt_bufferDirection",
    "bt_weeklyHours", "bt_minLeadDays", "bt_instructionEnabled", "bt_isActive"
  ) VALUES (
    'renewal', '續約預約（線上續約）', '續約', '2006833424-znZYKjip',
    'for-system-use/2', 'ragicTenantUid', 'go-back/1',
    90, 90, '09:00', '18:00', 0, 'both',
    '{"0":{"start":"13:00","end":"20:30"},"1":{"start":"10:00","end":"18:30"},"2":{"start":"16:00","end":"18:30"},"3":{"start":"13:00","end":"20:30"},"4":null,"5":{"start":"10:00","end":"18:30"},"6":null}'::jsonb,
    6, false, true
  ) RETURNING bt_id INTO renewal_id;

  INSERT INTO booking.calendar_routing_rules (
    "crr_templateId", crr_days, "crr_calendarId", "crr_calendarLabel",
    "crr_ownerName", "crr_sortOrder"
  ) VALUES (
    renewal_id, '[0,1,2,3,5]'::jsonb, 'chantel.oneplace@gmail.com',
    '謝依蒨', '謝依蒨', 0
  );

  -- ONE-147 verified four-field order; dedicated renewal date UI remains in the app.
  -- General notes / occupancy do not map to the extension-fee field 1013722.
  INSERT INTO booking.booking_form_fields (
    "bff_templateId", "bff_fieldType", bff_label, "bff_isRequired",
    bff_options, "bff_ragicFieldId", "bff_sortOrder"
  ) VALUES
    (renewal_id, 'select', '繳費方式', true, '["月繳","半年繳","年繳"]'::jsonb, '1013721', 0),
    (renewal_id, 'text', '入住人數', true, NULL, NULL, 1),
    (renewal_id, 'text', '續約備註', false, NULL, NULL, 2),
    (renewal_id, 'inbox_url', '', false, NULL, '1022936', 3);

  IF (SELECT count(*) FROM booking.calendar_routing_rules WHERE "crr_templateId" = renewal_id) <> 1
    OR (SELECT count(*) FROM booking.booking_form_fields WHERE "bff_templateId" = renewal_id) <> 4 THEN
    RAISE EXCEPTION 'renewal restore failed verification';
  END IF;
END
$restore$;
